-- Explicitly SYNTHETIC final-stage DATA. No genuine source/operator authority.
create temporary table launch_original as select rollout,public.fcf_native800_receipt('es-ct-tercera-g9')receipt from fcf_target_packets;
select pg_temp.six_assert((select activation_result->>'kind'='fcf-native800-price-before'and activation_result->'offTargetPriors'=private_fcf_native800.off_target_priors()and(activation_result#>>'{offTargetPriors,count}')::int>=1 from private_fcf_future_target_release.receipts where competition_id=797),'actual atomic server anchor before pricing');
savepoint native800_legacy_receipt;
insert into private_fcf_future_target_release.receipts(competition_id,inventory_key,packet_sha256,packet_text,rollout_text,rollout_sha256,source_fingerprint,cleanup_before_sha256,imported_state_sha256,stage)select 783,repeat('e',64),pg_temp.native800_sha('{}'),'{}','{"kind":"TEST ONLY legacy unaffected"}',pg_temp.native800_sha('{"kind":"TEST ONLY legacy unaffected"}'),repeat('e',64),before_sha256,repeat('e',64),'imported'from private_fcf_future_history.cleanup_receipt;
select pg_temp.six_assert((select activation_result is null from private_fcf_future_target_release.receipts where competition_id=783),'legacy receipt insertion remains unchanged');
rollback to savepoint native800_legacy_receipt;
-- Deliberate stock-shaped positions/prices/target priors; position trigger uses
-- ordinary authoritative scoring. Off-target priors are never touched here.
update players set position=case when reg_st>=100000 then case when reg_st%1000=0 then'GK'when reg_st%1000 between 1 and 4 or reg_st%1000=200 then'DEF'when reg_st%1000 between 5 and 8 then'MID'else'FWD'end else position end,value=case when reg_st%1000=2 then 9 else 4 end,value_start=case when reg_st%1000=2 then 9 else 4 end where competition_id=797;
insert into position_priors(player_id,position,score,updated_at)select p.id,x.position,0.25,clock_timestamp()from players p cross join(values('GK'),('DEF'),('MID'),('FWD'))x(position)where p.competition_id=797 on conflict(player_id,position)do update set score=excluded.score,updated_at=excluded.updated_at;
do $$declare r bigint;begin for r in select id from rounds where competition_id=797 loop perform recompute_round_scores(r);end loop;perform osvezi_statistiko_igralcev(array(select id from players where competition_id=797));end$$;
create temporary table launch_squad(id bigint primary key,team bigint,position text);
do $$declare pos text;n int;i int;pid bigint;begin for pos,n in select *from(values('GK',2),('DEF',5),('MID',5),('FWD',3))q loop for i in 1..n loop select p.id into pid from players p where competition_id=797 and active and p.position=pos and not exists(select 1 from launch_squad where id=p.id)and(select count(*)from launch_squad where team=p.team_id)<3 order by value,id limit 1;perform pg_temp.six_assert(pid is not null,'synthetic legal15 player');insert into launch_squad select id,team_id,position from players where id=pid;end loop;end loop;end$$;
create temporary table native800_ready(d jsonb);
do $$declare v jsonb;p jsonb;mp jsonb;projection jsonb;native jsonb;input jsonb;proposal jsonb;prices jsonb;replay jsonb;d jsonb;imp jsonb;ks text[];country bigint;gap int;later int;last_played int;selected int;rid bigint;earliest timestamptz;deadline timestamptz;opening date;begin
 select rollout,receipt into v,imp from launch_original;v:=private_fcf_native800.validate(v::text,pg_temp.native800_sha(v::text));p:=(v->>'targetPacketText')::jsonb;mp:=(v#>>'{identityPlan,mappingText}')::jsonb;select country_id into country from competitions where id=797;select coalesce(array_agg(distinct k order by k),'{}')into ks from(select public.anonimizacijski_kljuc(country||'|reg|'||a.reg)k from pg_temp._fcf_apps a union select public.anonimizacijski_kljuc(country||'|'||(a.x->>'ime'))from pg_temp._fcf_apps a)keys;
 projection:=private_fcf_future_projection.capture('es-ct-tercera-g9',ks);native:=projection->'native';gap:=private_fcf_future_activation.next_round(797,0,clock_timestamp());select count(distinct rn)into later from pg_temp._fcf_expected where f->>'statisticsStatus'='available'and rn>gap;select coalesce(max(rn),0)into last_played from pg_temp._fcf_expected where f->>'statisticsStatus'='available'and(rn<gap or later>2);selected:=case when gap>last_played then gap else private_fcf_future_activation.next_round(797,last_played,clock_timestamp())end;select id into rid from rounds where competition_id=797 and number=selected;earliest:=private_fcf_future_activation.official_clock(selected);deadline:=earliest-interval'6 hours';select min((f->>'date')::date)into opening from pg_temp._fcf_expected where rn=selected;
 input:=jsonb_build_object('targetSlug','es-ct-tercera-g9','competitionId',797,'sourceCode','4118349-4118588','season','2026/27','sourceFingerprintSha256',v#>>'{inventoryBinding,sourceFingerprintSha256}','writerCommit',v->>'sourceCommit','fixtures',(select jsonb_agg(f order by id)from pg_temp._fcf_expected),'mapping',(select jsonb_agg(m order by m->>'sourceMatchId')from jsonb_array_elements(mp->'fixtures')m),'native',native);
 proposal:=jsonb_build_object('schemaVersion',1,'kind','fcf-future-launch-proposal','targetSlug','es-ct-tercera-g9','competitionId',797,'season','2026/27','sourceCode','4118349-4118588','sourceFingerprintSha256',v#>>'{inventoryBinding,sourceFingerprintSha256}','writerCommit',v->>'sourceCommit','projectionSha256',pg_temp.native800_sha(pg_temp.native800_canonical(input)),'roundNumber',selected,'roundId',rid,'firstFantasyPlayedOn',opening,'timeZone','Europe/Madrid','earliestKickoffUTC',to_char(earliest at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'deadlineUTC',to_char(deadline at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'fixtureIds',(select jsonb_agg(id order by id)from pg_temp._fcf_expected where rn=selected),'matchIds',(select jsonb_agg(mid order by mid)from pg_temp._fcf_expected where rn=selected));
 select jsonb_agg(jsonb_build_object('id',id,'value',value,'value_start',value_start,'position',position,'position_source',position_source)order by id)into prices from players where competition_id=797;replay:=jsonb_build_object('schemaVersion',1,'kind','fcf-target-price-replay','targetSlug','es-ct-tercera-g9','competitionId',797,'season','2026/27','modelSha256','964854cd20fae2e58d4ba74156ca2be8aa9de0e3c8d69340f0a0a92211118f67','computedCount',jsonb_array_length(prices),'threshold',270,'players',prices);
 d:=jsonb_build_object('schemaVersion',1,'kind','fcf-g9-native800-readiness-data','protocol','fcf-g9-native800-v1','targetSlug','es-ct-tercera-g9','sourceBinding',v->'inventoryBinding','capture',v#>'{inventoryBinding,currentCapture}','originalImport',jsonb_build_object('stage','imported','receiptId',imp->>'receiptId','rolloutText',imp->>'rolloutText','rolloutSha256',imp->>'rolloutSha256','targetPacketSha256',imp->>'targetPacketSha256','sourceFingerprintSha256',imp->>'sourceFingerprintSha256','importedStateSha256',imp->>'importedStateSha256','currentStateSha256',imp->>'currentStateSha256','currentActive',false),'nativeSnapshotText',projection->>'dependencySnapshotText','nativeSnapshotSha256',projection->>'dependencySnapshotSha256','scoreBeforeimages',jsonb_build_object('selectedG9',private_fcf_native800.score_state(797),'offTargetG1',private_fcf_native800.score_state(783)),'pricingSnapshotText',projection#>>'{pricingSnapshot,snapshotText}','pricingSnapshotSha256',projection#>>'{pricingSnapshot,snapshotSha256}','pricingReplayText',replay::text,'pricingReplaySha256',pg_temp.native800_sha(replay::text),'modelSha256',replay->>'modelSha256','priceVector',prices,'cheapestLegal15',public.najcenejsi_kader(public.stanje_lige(797)->'igralci'),'legal15PlayerIds',(select jsonb_agg(id order by id)from launch_squad),'launchProposal',proposal,'admissible',false,'nativeAdmission',false,'activationEligible',false);insert into native800_ready values(d);
end$$;
select pg_temp.six_assert((select(d->>'nativeSnapshotText')::jsonb#>'{privacy,checkedKeys}'=((d#>>'{originalImport,rolloutText}')::jsonb->>'targetPacketText')::jsonb#>'{databaseInventory,identityPrivacy,checkedKeys}'from native800_ready),'postprice prepared privacy keys retain actual original native country/source identity');
create function pg_temp.native800_launch_gate(activate boolean)returns jsonb language plpgsql as $$declare d jsonb;v jsonb;s jsonb;t text;begin select x.d into d from native800_ready x;v:=(d#>>'{originalImport,rolloutText}')::jsonb;s:=pg_temp.native800_attest(v,'check')::jsonb;s:=s||jsonb_build_object('kind','fcf-native800-launch-stage-attestation','stage','launch','readinessSha256',pg_temp.native800_sha(d::text));t:=s::text;return public.fcf_native800_launch(d::text,pg_temp.native800_sha(d::text),activate,t,pg_temp.native800_sha(t));end$$;
create temporary table launch_before as select private_fcf_native800.launch_after_image(797)state,(select to_jsonb(r)from private_fcf_future_target_release.receipts r where competition_id=797)receipt;
select pg_temp.six_assert(pg_temp.native800_launch_gate(false)->>'stage'='checked','actual postprice drycheck');
select pg_temp.six_assert(private_fcf_native800.launch_after_image(797)=(select state from launch_before)and(select to_jsonb(r)from private_fcf_future_target_release.receipts r where competition_id=797)=(select receipt from launch_before),'drycheck makes no durable writes');
create function pg_temp.native800_launch_mutant(command text,label text,expected_error text default null)returns void language plpgsql as $$declare baseline jsonb;receipt jsonb;begin baseline:=private_fcf_native800.launch_after_image(797);select to_jsonb(r)into receipt from private_fcf_future_target_release.receipts r where competition_id=797;begin execute command;perform pg_temp.native800_launch_gate(true);raise exception 'NATIVE800 LAUNCH TEST: accepted %',label;exception when others then if(sqlerrm not like'FCF_TARGET:%'and sqlerrm not like'HISTORICAL_POLICY:%')or(expected_error is not null and sqlerrm<>expected_error)then raise;end if;end;perform pg_temp.six_assert(private_fcf_native800.launch_after_image(797)=baseline and(select to_jsonb(r)from private_fcf_future_target_release.receipts r where competition_id=797)=receipt,'refusal rolls back all mutation and attempted launch: '||label);end$$;
-- Coherently reprepare actual NULL state so this tests the COMPLETE-deadline
-- gate itself, not merely an old optimistic-concurrency snapshot hash.
select pg_temp.native800_launch_mutant($null_deadline$update rounds set deadline_at=null where competition_id=797 and number=1;update native800_ready n set d=n.d||jsonb_build_object('nativeSnapshotText',fresh.p->>'dependencySnapshotText','nativeSnapshotSha256',fresh.p->>'dependencySnapshotSha256','pricingSnapshotText',fresh.p#>>'{pricingSnapshot,snapshotText}','pricingSnapshotSha256',fresh.p#>>'{pricingSnapshot,snapshotSha256}')from(select private_fcf_future_projection.capture('es-ct-tercera-g9',array(select jsonb_array_elements_text(((select d->>'nativeSnapshotText'from native800_ready)::jsonb)#>'{privacy,checkedKeys}')))p)fresh;$null_deadline$,'coherent NULL historical deadline','FCF_TARGET: complete current native round dates/deadlines');
