select pg_temp.six_assert(not has_function_privilege('anon','public.fcf_native800_launch(text,text,boolean,text,text)','execute')and not has_function_privilege('authenticated','public.fcf_native800_launch(text,text,boolean,text,text)','execute')and has_function_privilege('service_role','public.fcf_native800_launch(text,text,boolean,text,text)','execute')and not has_function_privilege('service_role','private_fcf_native800.price_anchor()','execute'),'strict public/service and private trigger ACL');
